DOMAIN3 = [{'num': 3, 'topic': 3, 'title': 'Create an analyst profile', 'objective': 'LO1', 'desc': 'A profile bundles reproducible columns, coloring rules and protocol settings.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Create a profile named C1123-Analyst using Edit > Configuration Profiles. Keep the original profile available.', ''), ('Open data/branch-office.pcap. Disable network name resolution in View > Name Resolution. Record numeric client, server and resolver IP addresses.', ''), ('Select a TCP packet. Expand TCP and right-click Stream index > Apply as Column. Add frame.time_delta_displayed as a custom column using Preferences > Appearance > Columns.', ''), ('Apply dns and inspect the profile name and displayed columns. Copy the profile folder path from Help > About Wireshark > Folders into outputs/findings.md. Export or copy your profile to outputs/profile/ without overwriting a colleague profile.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied dns expression matches 6 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 45}]
